USE gmu_events;

UPDATE event_registrations
SET details_json = '{"is_festival": true, "sub_events": [{"name": "Keynote Speech", "description": "Join us for an inspiring opening address by Dr. Alan Turing, a pioneer in the field of Artificial Intelligence. He will be discussing the evolution of neural networks, the ethical implications of AGI, and where the industry is heading in the next decade. Don''t miss this opportunity to hear from one of the greatest minds in tech!"}, {"name": "Workshop 1: Neural Networks", "description": "A comprehensive, hands-on workshop tailored for students and early-career developers. We will dive deep into building your very first neural network using PyTorch. You will learn about backpropagation, activation functions, and how to optimize your models for real-world datasets. Please bring your laptops with Python pre-installed."}], "sub_events_logistics": [{"name": "Keynote Speech", "venue": "Main Auditorium", "start_time": "10:00", "end_time": "12:00", "description": "Join us for an inspiring opening address by Dr. Alan Turing, a pioneer in the field of Artificial Intelligence. He will be discussing the evolution of neural networks, the ethical implications of AGI, and where the industry is heading in the next decade. Don''t miss this opportunity to hear from one of the greatest minds in tech!"}, {"name": "Workshop 1: Neural Networks", "venue": "Lab 1", "start_time": "13:00", "end_time": "15:00", "description": "A comprehensive, hands-on workshop tailored for students and early-career developers. We will dive deep into building your very first neural network using PyTorch. You will learn about backpropagation, activation functions, and how to optimize your models for real-world datasets. Please bring your laptops with Python pre-installed."}]}'
WHERE id = 1207;
